'use strict';
const $ = s => document.querySelector(s);
const nowISO = () => new Date().toISOString();
const fmtTime = d => new Date(d).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const seed = () => {
 const records=[]; const base=new Date();
 for(let i=13;i>=0;i--){const d=new Date(base);d.setDate(d.getDate()-i);const n=i;
 records.push({id:'seed-'+i,date:d.toISOString(),hr:68+Math.round(Math.sin(i*.8)*5)+(i===2?12:0),spo2:97+Math.round(Math.cos(i*.7)),temp:36.5+((i%4)*.1),systolic:112+(i%5)*2,diastolic:72+(i%4),sleep:+(7.1+Math.sin(i*.6)*.8).toFixed(1),stress:Math.max(1,Math.min(8,3+Math.round(Math.cos(i)*2))),exercise:35+(i%4)*8,radiation:+(0.08+(i%5)*.012).toFixed(3),mood:['Good','Steady','Focused','Tired'][i%4],quality:['Good','Fair','Good','Very good'][i%4],interruptions:i%3,notes:'Synthetic mission training record',source:'SYNTHETIC DEMO'});
 }return records;
};
const defaults={profile:{name:'Rebekka M. (Demo)',crewId:'AC-042',mission:'AURORA-1 / Mars Transit Simulation',missionDay:142,role:'Mission Specialist',baseline:{hr:70,spo2:98,temp:36.6,systolic:115,diastolic:75,sleep:7.5,stress:3}},records:seed(),alerts:[],settings:{hrLow:50,hrHigh:110,spo2Low:94,tempLow:35.5,tempHigh:38.0,sleepLow:6,stressHigh:7,radLimit:20,delayed:true},pendingReports:[],mental:[],exerciseLog:[],boneLog:[]};
let state; try{state=JSON.parse(localStorage.getItem('astrocare-state'))||defaults}catch(e){state=defaults}
const save=()=>localStorage.setItem('astrocare-state',JSON.stringify(state));
let activePage='overview',chartObjects=[],researchMetric='hemoglobin',researchSubject='C001';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const latest=()=>state.records.slice().sort((a,b)=>new Date(b.date)-new Date(a.date))[0]||{};
const sorted=()=>state.records.slice().sort((a,b)=>new Date(a.date)-new Date(b.date));
const avg=key=>{let a=state.records.slice(-7).map(x=>Number(x[key])).filter(Number.isFinite);return a.length?a.reduce((x,y)=>x+y,0)/a.length:0};
const toast=msg=>{const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)};
function addAlert(severity,parameter,reason,advice,recordId){state.alerts.unshift({id:'a-'+Date.now()+'-'+Math.random().toString(16).slice(2),date:nowISO(),severity,parameter,reason,advice,recordId,status:'OPEN'});}
function analyse(r){const s=state.settings,b=state.profile.baseline;let found=[];
 const tests=[['Heart rate',r.hr< s.hrLow||r.hr>s.hrHigh,`Heart rate ${r.hr} bpm is outside your configured demonstration range (${s.hrLow}–${s.hrHigh} bpm).`,'Review symptoms and repeat the measurement; contact the onboard medical officer according to mission protocol.'],['SpO₂',r.spo2<s.spo2Low,`SpO₂ ${r.spo2}% is below the configured demonstration threshold (${s.spo2Low}%).`,'Verify sensor placement and repeat; follow the approved medical protocol if persistent.'],['Temperature',r.temp<s.tempLow||r.temp>s.tempHigh,`Temperature ${r.temp}°C is outside the configured demonstration range (${s.tempLow}–${s.tempHigh}°C).`,'Repeat measurement with a validated device and seek medical review if persistent.'],['Sleep',r.sleep<s.sleepLow,`Sleep duration ${r.sleep} h is below the configured ${s.sleepLow} h flag threshold.`,'Consider protected sleep opportunity and review workload / schedule with the crew support team.'],['Stress',r.stress>=s.stressHigh,`Self-reported stress ${r.stress}/10 reached the configured flag threshold (${s.stressHigh}/10).`,'Try a brief grounding exercise and consider a private check-in with crew support.'],['Baseline HR',Math.abs(r.hr-b.hr)>20,`Heart rate differs from the personal baseline (${b.hr} bpm) by more than 20 bpm.`,'Check context, activity and repeat at rest; this prototype does not diagnose a condition.']];
 tests.forEach(([p,ok,reason,advice])=>{if(ok)found.push({p,reason,advice})});
 found.forEach(x=>addAlert((x.p==='SpO₂'||x.p==='Temperature')?'WARNING':'WARNING',x.p,x.reason,x.advice,r.id));
 const cumulativeDose=state.records.reduce((sum,item)=>sum+(Number(item.radiation)||0),0);
 if(cumulativeDose>Number(s.radLimit))addAlert('WARNING','Radiation dose',`Sum of logged manual/demo dose entries (${cumulativeDose.toFixed(3)} mSv) exceeds your configured demonstration limit ${s.radLimit} mSv.`,'Verify against the spacecraft dosimeter record and mission radiation officer guidance.',r.id);
 return found;
}
function chart(canvasId,series,labels,opts={}){const c=document.getElementById(canvasId);if(!c)return;const ctx=c.getContext('2d');const dpr=window.devicePixelRatio||1;const w=c.clientWidth||500,h=c.clientHeight||170;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const pad={l:34,r:10,t:12,b:24},cw=w-pad.l-pad.r,ch=h-pad.t-pad.b;let vals=series.flatMap(s=>s.values).filter(v=>Number.isFinite(v));let min=opts.min??(vals.length?Math.floor(Math.min(...vals)*.94):0),max=opts.max??(vals.length?Math.ceil(Math.max(...vals)*1.04):1);if(!Number.isFinite(min)||!Number.isFinite(max)){min=0;max=1}if(min===max){min-=1;max+=1}const x=i=>pad.l+(series[0].values.length<2?0:i/(series[0].values.length-1))*cw;const y=v=>pad.t+(max-v)/(max-min)*ch;ctx.font='9px DM Mono, monospace';ctx.fillStyle='#7891a7';ctx.strokeStyle='#20384e';ctx.lineWidth=1;for(let j=0;j<=4;j++){let yy=pad.t+j*ch/4;ctx.beginPath();ctx.moveTo(pad.l,yy);ctx.lineTo(w-pad.r,yy);ctx.stroke();ctx.fillText((max-(max-min)*j/4).toFixed(opts.decimals??0),2,yy+3)}labels.forEach((l,i)=>{if(i%Math.ceil(labels.length/5)===0||i===labels.length-1){ctx.fillStyle='#7891a7';ctx.fillText(l,pad.l+(i/(labels.length-1||1))*cw-10,h-5)}});series.forEach((s,si)=>{ctx.strokeStyle=s.color||'#55d9ed';ctx.lineWidth=2;ctx.beginPath();s.values.forEach((v,i)=>{if(!Number.isFinite(v))return;let xx=x(i),yy=y(v);i?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy)});ctx.stroke();s.values.forEach((v,i)=>{if(!Number.isFinite(v))return;ctx.fillStyle=s.color||'#55d9ed';ctx.beginPath();ctx.arc(x(i),y(v),2.5,0,Math.PI*2);ctx.fill()})});}
function spark(id,key,color){const r=sorted().slice(-8);chart(id,[{values:r.map(x=>+x[key]),color}],r.map((_,i)=>''),{min:Math.min(...r.map(x=>+x[key]))-1,max:Math.max(...r.map(x=>+x[key]))+1});}
function metric(label,value,unit,icon,foot,id,key,color='#55d9ed'){return `<div class="card metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}<small> ${unit}</small></div><div class="metric-foot">${foot}</div><canvas class="metric-spark" id="${id}"></canvas></div>`}
function status(){let open=state.alerts.filter(a=>a.status==='OPEN');return open.some(a=>a.severity==='CRITICAL')?['Critical','critical']:open.length?['Review recommended','warn']:['Within configured demo limits',''];}
function pageOverview(){let r=latest(),s=status(),rs=sorted().slice(-7),labels=rs.map(x=>new Date(x.date).toLocaleDateString([],{month:'numeric',day:'numeric'}));return `<div class="section-head"><div><h2>Flight crew health snapshot</h2><p>Personalised trend view · Synthetic telemetry · ${esc(state.profile.mission)}</p></div><div class="btn-row"><button class="btn secondary" id="add-record">＋ Add reading</button><button class="btn primary" id="export-report">Export medical summary ↓</button></div></div>
<div class="grid metrics">${metric('Heart rate',r.hr??'—','bpm','♡',`Baseline ${state.profile.baseline.hr} bpm`,'spark-hr','hr')}${metric('Blood oxygen',r.spo2??'—','%','◉',`Baseline ${state.profile.baseline.spo2}%`,'spark-spo2','spo2')}${metric('Body temperature',r.temp??'—','°C','♨',`Baseline ${state.profile.baseline.temp} °C`,'spark-temp','temp')}${metric('Blood pressure',`${r.systolic??'—'}/${r.diastolic??'—'}`,'mmHg','⌁','Manually entered demo reading','spark-bp','systolic')}</div>
<div class="grid overview-grid"><div class="card chart-card"><div class="card-head"><div><h3>Physiological trend</h3><small>HEART RATE · LAST 14 RECORDS</small></div><span class="pill">DEMO TELEMETRY</span></div><div class="chart-wrap"><canvas id="overview-chart"></canvas></div></div><div class="card"><div class="card-head"><h3>Mission health status</h3><small>RULE-BASED REVIEW</small></div><div class="status-card"><div class="status-orb">${s[1]?'!':'✓'}</div><div><strong>${s[0]}</strong><span>Based on configured demo thresholds</span></div><span class="tag ${s[1]}">${s[1]?'REVIEW':'NOMINAL'}</span></div><div class="card-head"><h3>Recent alerts</h3><button class="text-link" data-go="alerts">View all →</button></div>${alertRows(state.alerts.slice(0,3))}</div></div>
<div class="grid three-col" style="margin-top:14px"><div class="card"><div class="card-head"><h3>Sleep & recovery</h3><small>LAST RECORD</small></div><div class="metric-value">${r.sleep??'—'}<small> h</small></div><div class="metric-foot">Sleep quality: ${esc(r.quality||'Not recorded')}</div><div class="progress"><span style="width:${Math.min(100,(r.sleep||0)/8*100)}%"></span></div></div><div class="card"><div class="card-head"><h3>Exercise session</h3><small>LAST RECORD</small></div><div class="metric-value">${r.exercise??'—'}<small> min</small></div><div class="metric-foot">Record resistance / aerobic activity in Bone & Muscle.</div></div><div class="card"><div class="card-head"><h3>Radiation log</h3><small>MANUAL / DEMO</small></div><div class="metric-value">${r.radiation??'—'}<small> mSv</small></div><div class="metric-foot">Not a spacecraft dosimeter feed.</div></div></div>`}
function alertRows(list){if(!list.length)return `<div class="empty">No alerts currently open. New alerts appear when configured demo rules are met.</div>`;return `<div class="alert-list">${list.map(a=>`<div class="alert-row"><span class="alert-mark ${a.severity==='CRITICAL'?'critical':''}"></span><div><strong>${esc(a.parameter)} · ${esc(a.severity)}</strong><p>${esc(a.reason)}</p></div><time>${fmtTime(a.date)}</time></div>`).join('')}</div>`}
function pageVitals(){let r=latest();return `<div class="section-head"><div><h2>Vital signs monitoring</h2><p>Measurements are entered or simulated locally. Configure personal baselines in Settings.</p></div><button class="btn primary" id="add-record">＋ Add health reading</button></div><div class="grid metrics">${metric('Heart rate',r.hr,'bpm','♡','Resting / activity context matters','v-hr','hr')}${metric('SpO₂',r.spo2,'%','◉','Oxygen saturation estimate','v-sp','spo2')}${metric('Temperature',r.temp,'°C','♨','Body temperature entry','v-t','temp')}${metric('Blood pressure',`${r.systolic}/${r.diastolic}`,'mmHg','⌁','Manual cuff reading','v-bp','systolic')}</div><div class="grid two-col" style="margin-top:14px"><div class="card"><div class="card-head"><h3>Heart rate trend</h3><small>BPM</small></div><div class="chart-wrap"><canvas id="vital-hr"></canvas></div></div><div class="card"><div class="card-head"><h3>Oxygen saturation trend</h3><small>%</small></div><div class="chart-wrap"><canvas id="vital-sp"></canvas></div></div><div class="card"><div class="card-head"><h3>Temperature trend</h3><small>°C</small></div><div class="chart-wrap"><canvas id="vital-temp"></canvas></div></div><div class="card"><div class="card-head"><h3>Blood pressure trend</h3><small>MMHG</small></div><div class="chart-wrap"><canvas id="vital-bp"></canvas></div></div></div><p class="notice" style="margin-top:13px">Clinical note: these prototype thresholds are configurable demonstration flags, not universal astronaut medical limits. No vital signs are collected from real sensors.</p>`}
function pageCardio(){let r=latest(),rs=sorted().slice(-14),labels=rs.map(x=>new Date(x.date).toLocaleDateString([],{month:'numeric',day:'numeric'}));return `<div class="section-head"><div><h2>Cardiovascular monitoring</h2><p>Trend awareness for heart rate, blood pressure and oxygen saturation.</p></div><span class="pill">NO SENSOR CONNECTION</span></div><div class="grid three-col"><div class="mini-stat"><span>Latest heart rate</span><strong>${r.hr} bpm</strong><span>Personal baseline ${state.profile.baseline.hr} bpm</span></div><div class="mini-stat"><span>Latest blood pressure</span><strong>${r.systolic}/${r.diastolic}</strong><span>mmHg · manual / demo</span></div><div class="mini-stat"><span>Latest SpO₂</span><strong>${r.spo2}%</strong><span>Personal baseline ${state.profile.baseline.spo2}%</span></div></div><div class="grid two-col" style="margin-top:14px"><div class="card"><div class="card-head"><h3>Heart rate history</h3><small>14 RECORDS</small></div><div class="chart-wrap"><canvas id="card-hr"></canvas></div></div><div class="card"><div class="card-head"><h3>Blood pressure history</h3><small>SYSTOLIC / DIASTOLIC</small></div><div class="chart-wrap"><canvas id="card-bp"></canvas></div></div></div><div class="card" style="margin-top:14px"><h3 class="panel-title">Why monitor cardiovascular adaptation?</h3><p class="notice">Microgravity changes fluid distribution and cardiovascular loading. NASA human research includes cardiovascular and sensorimotor measurements; this dashboard provides a place to track user-entered values and review changes against an individual baseline. It does not infer cardiovascular disease or replace clinical assessment.</p><a class="text-link" href="https://www.nasa.gov/hrp/" target="_blank" rel="noopener">NASA Human Research Program →</a></div>`}
function pageBone(){let ex=state.exerciseLog.slice(-10),r=latest();return `<div class="section-head"><div><h2>Bone & muscle health</h2><p>Countermeasure adherence and self-reported observations — not a bone-density measurement.</p></div><button class="btn primary" id="log-exercise">＋ Log exercise / observation</button></div><div class="grid three-col"><div class="mini-stat"><span>Latest exercise</span><strong>${r.exercise} min</strong><span>From synthetic / entered record</span></div><div class="mini-stat"><span>Exercise logs</span><strong>${state.exerciseLog.length}</strong><span>Saved locally</span></div><div class="mini-stat"><span>Bone density</span><strong>Not measured</strong><span>No DXA / medical instrument connected</span></div></div><div class="grid two-col" style="margin-top:14px"><div class="card"><div class="card-head"><h3>Exercise duration</h3><small>MINUTES / LOG</small></div><div class="chart-wrap"><canvas id="bone-chart"></canvas></div></div><div class="card"><h3 class="panel-title">Spaceflight relevance</h3><p class="notice">Reduced mechanical loading in microgravity contributes to skeletal unloading and muscle deconditioning. Exercise countermeasures, including resistance exercise, are important parts of crew health strategies. Logs here track duration and perceived symptoms only; they cannot quantify bone mineral density, muscle mass or strength.</p><div class="recommendation">Record exercise type, duration, perceived effort and any pain or unusual fatigue. Share persistent symptoms with the medical officer.</div></div></div><div class="card" style="margin-top:14px"><h3 class="panel-title">Recent exercise & observations</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>DATE</th><th>TYPE</th><th>DURATION</th><th>EFFORT</th><th>OBSERVATION</th></tr></thead><tbody>${ex.slice().reverse().map(x=>`<tr><td>${fmtTime(x.date)}</td><td>${esc(x.type)}</td><td>${x.duration} min</td><td>${x.effort}/10</td><td>${esc(x.note||'—')}</td></tr>`).join('')||'<tr><td colspan="5">No exercise logs yet.</td></tr>'}</tbody></table></div></div>`}
function pageSleep(){let r=latest(),rs=sorted().slice(-14),labels=rs.map(x=>new Date(x.date).toLocaleDateString([],{month:'numeric',day:'numeric'}));return `<div class="section-head"><div><h2>Sleep & fatigue monitoring</h2><p>Sleep duration, quality, interruptions and self-reported fatigue indicators.</p></div><button class="btn primary" id="sleep-check">＋ Sleep check-in</button></div><div class="grid three-col"><div class="mini-stat"><span>Latest sleep</span><strong>${r.sleep} h</strong><span>Configured flag below ${state.settings.sleepLow} h</span></div><div class="mini-stat"><span>Interruptions</span><strong>${r.interruptions??'—'}</strong><span>Self-reported / demo</span></div><div class="mini-stat"><span>Quality</span><strong>${esc(r.quality||'—')}</strong><span>Subjective check-in</span></div></div><div class="grid two-col" style="margin-top:14px"><div class="card"><div class="card-head"><h3>Sleep duration trend</h3><small>HOURS</small></div><div class="chart-wrap"><canvas id="sleep-chart"></canvas></div></div><div class="card"><h3 class="panel-title">Sleep and circadian rhythm in space</h3><p class="notice">Spaceflight schedules, artificial lighting, workload and mission operations can challenge sleep and circadian alignment. NASA describes actigraphy and sleep questionnaires in spaceflight standard measures. ASTROCARE does not receive actigraphy data; sleep values are manual or synthetic entries.</p><div class="recommendation">Protect a consistent sleep opportunity, manage light exposure around the planned sleep period, and report persistent fatigue or disrupted sleep to the crew medical/support team.</div><a class="text-link" href="https://www.nasa.gov/human-systems-integration-division/human-performance/fatigue-countermeasures-laboratory/" target="_blank" rel="noopener">NASA Fatigue Countermeasures Laboratory →</a></div></div>`}
function pageMental(){return `<div class="section-head"><div><h2>Mental wellness check-in</h2><p>Private, non-diagnostic self-reflection. Saved on this device only.</p></div></div><div class="grid two-col"><div class="card"><h3 class="panel-title">Daily crew wellness</h3><form id="mental-form" class="form-grid"><label>Mood<select name="mood"><option>Good</option><option>Steady</option><option>Low</option><option>Anxious</option><option>Irritable</option><option>Overwhelmed</option></select></label><label>Stress (0–10)<input name="stress" type="number" min="0" max="10" value="3"></label><label>Feeling connected to crew<select name="connected"><option>Well connected</option><option>Somewhat connected</option><option>Isolated</option></select></label><label>Energy<select name="energy"><option>Good</option><option>Moderate</option><option>Low</option></select></label><label class="wide">Anything you want to note?<textarea name="note" rows="3" placeholder="Optional. Keep sensitive notes private."></textarea></label><div class="wide"><button class="btn primary">Save private check-in</button></div></form></div><div class="card"><h3 class="panel-title">Supportive strategies</h3><div class="timeline"><div class="timeline-item"><strong>Maintain social connection</strong><p>Plan regular crew conversations and private contact with trusted support when communication windows permit.</p></div><div class="timeline-item"><strong>Protect personal routines</strong><p>Use predictable daily routines, leisure time and sleep opportunities where mission operations allow.</p></div><div class="timeline-item"><strong>Use brief grounding</strong><p>Try slow breathing, a short mindfulness exercise or a familiar relaxing activity.</p></div><div class="timeline-item"><strong>Seek human support</strong><p>Discuss persistent distress, isolation or changes in functioning with qualified crew support or medical personnel.</p></div></div><p class="notice">This is not a psychological diagnostic instrument or crisis service. In an actual mission, follow approved crew support and emergency procedures.</p></div></div><div class="card" style="margin-top:14px"><h3 class="panel-title">Recent check-ins</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>DATE</th><th>MOOD</th><th>STRESS</th><th>CONNECTION</th><th>ENERGY</th></tr></thead><tbody>${state.mental.slice().reverse().slice(0,10).map(x=>`<tr><td>${fmtTime(x.date)}</td><td>${esc(x.mood)}</td><td>${x.stress}/10</td><td>${esc(x.connected)}</td><td>${esc(x.energy)}</td></tr>`).join('')||'<tr><td colspan="5">No check-ins recorded.</td></tr>'}</tbody></table></div></div>`}
function pageRadiation(){let r=latest(),rs=sorted().slice(-14),lim=Number(state.settings.radLimit);return `<div class="section-head"><div><h2>Space radiation exposure</h2><p>Manual / synthetic dose log. No spacecraft dosimeter connection.</p></div><button class="btn primary" id="add-record">＋ Add dose entry</button></div><div class="grid three-col"><div class="mini-stat"><span>Sum of logged entries</span><strong>${state.records.reduce((sum,x)=>sum+(Number(x.radiation)||0),0).toFixed(3)} mSv</strong><span>Manual / synthetic entries only</span></div><div class="mini-stat"><span>Configured demo threshold</span><strong>${lim} mSv</strong><span>Editable in Settings</span></div><div class="mini-stat"><span>Data source</span><strong>Manual / Demo</strong><span>Not SRAG telemetry</span></div></div><div class="grid two-col" style="margin-top:14px"><div class="card"><div class="card-head"><h3>Entered exposure history</h3><small>MSV / RECORD</small></div><div class="chart-wrap"><canvas id="rad-chart"></canvas></div></div><div class="card"><h3 class="panel-title">Why track radiation?</h3><p class="notice">Space radiation includes energetic particles that can contribute to astronaut health risk. NASA's Space Radiation Analysis Group supports operational monitoring and dosimetry. Exposure interpretation depends on radiation type, energy, shielding, mission context and dose quantity; this prototype's single mSv field is a simplified manual log, not a validated dose assessment.</p><a class="text-link" href="https://www.nasa.gov/directorates/esdmd/hhp/space-radiation/" target="_blank" rel="noopener">NASA Space Radiation overview →</a><div class="recommendation">Use actual calibrated dosimeter outputs and approved mission radiation guidance for operational decisions.</div></div></div>`}
function pageAlerts(){let list=state.alerts;return `<div class="section-head"><div><h2>Emergency & alert centre</h2><p>Rule-based prototype alerts · Local queue for delayed communications.</p></div><div class="btn-row"><button class="btn secondary" id="export-alerts">Export alert summary</button><button class="btn secondary" id="sync-alerts">Simulate comms available</button></div></div><div class="grid three-col"><div class="mini-stat"><span>Open alerts</span><strong>${list.filter(x=>x.status==='OPEN').length}</strong></div><div class="mini-stat"><span>Critical</span><strong>${list.filter(x=>x.severity==='CRITICAL'&&x.status==='OPEN').length}</strong></div><div class="mini-stat"><span>Queued reports</span><strong>${state.pendingReports.length}</strong></div></div><div class="card" style="margin-top:14px"><div class="card-head"><h3>Alert history</h3><small>LOCAL RECORDS</small></div><div class="table-scroll"><table class="data-table"><thead><tr><th>TIME</th><th>SEVERITY</th><th>PARAMETER</th><th>REASON</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${list.map(a=>`<tr><td>${fmtTime(a.date)}</td><td><span class="tag ${a.severity==='CRITICAL'?'critical':'warn'}">${a.severity}</span></td><td>${esc(a.parameter)}</td><td>${esc(a.reason)}</td><td>${a.status}</td><td><button class="btn secondary" data-resolve="${a.id}">${a.status==='OPEN'?'Acknowledge':'Reopen'}</button></td></tr>`).join('')||'<tr><td colspan="6">No alerts generated.</td></tr>'}</tbody></table></div></div><p class="notice" style="margin-top:12px">These alerts are not connected to a spacecraft alarm system. They are configurable demonstration flags only. Do not use for medical triage or emergency response; follow official onboard procedures.</p>`}
function pageHistory(){let list=sorted();return `<div class="section-head"><div><h2>Astronaut health history</h2><p>Search, review, export or delete locally stored records.</p></div><div class="btn-row"><button class="btn secondary" id="export-csv">Export CSV ↓</button><button class="btn primary" id="add-record">＋ Add record</button></div></div><div class="card"><div class="form-grid" style="margin-bottom:12px"><label>Search records<input id="history-search" placeholder="Search notes or parameter…"></label><label>Filter source<select id="history-filter"><option value="all">All records</option><option value="SYNTHETIC DEMO">Synthetic demo</option><option value="MANUAL ENTRY">Manual entry</option></select></label></div><div class="table-scroll"><table class="data-table"><thead><tr><th>DATE</th><th>HR</th><th>SpO₂</th><th>TEMP</th><th>BP</th><th>SLEEP</th><th>STRESS</th><th>SOURCE</th><th>ACTION</th></tr></thead><tbody id="history-body">${historyRows(list)}</tbody></table></div></div><div class="grid two-col" style="margin-top:14px"><div class="card"><h3 class="panel-title">Mission timeline</h3><div class="timeline">${list.slice(-5).reverse().map((x,i)=>`<div class="timeline-item"><strong>${fmtTime(x.date)} · Day ${Math.max(1,state.profile.missionDay-4+i)}</strong><p>HR ${x.hr} bpm · SpO₂ ${x.spo2}% · Sleep ${x.sleep} h · ${x.source}</p></div>`).join('')}</div></div><div class="card"><h3 class="panel-title">Data integrity</h3><p class="notice">Records are stored in this browser's localStorage. They are not encrypted, backed up, or transmitted to a medical team. Export a CSV or report to retain a copy. Avoid entering real sensitive medical data on shared devices.</p><button class="btn secondary" id="export-report">Generate medical summary</button></div></div>`}
function historyRows(list){return list.slice().reverse().map(r=>`<tr><td>${fmtTime(r.date)}</td><td>${r.hr}</td><td>${r.spo2}%</td><td>${r.temp}°</td><td>${r.systolic}/${r.diastolic}</td><td>${r.sleep}h</td><td>${r.stress}/10</td><td>${esc(r.source||'MANUAL ENTRY')}</td><td><button class="btn danger" data-delete="${r.id}">Delete</button></td></tr>`).join('')||'<tr><td colspan="9">No records.</td></tr>'}
function pageReferences(){return `<div class="section-head"><div><h2>References & NASA data sources</h2><p>Authentic research context is separated from synthetic dashboard telemetry.</p></div><span class="pill">RESEARCH TRACEABILITY</span></div><div class="card" style="margin-bottom:14px"><h3 class="panel-title">Data integration statement</h3><p class="notice">ASTROCARE does not currently display real-time NASA astronaut vital-sign measurements. The NASA Research Data page now integrates the processed OSD-569 CBC file supplied with this project: 28 rows from four coded Inspiration4 participants across seven pre-/post-flight ground timepoints. Its measured blood-cell variables are shown separately from synthetic dashboard telemetry. OSD-569 also includes molecular assays; the large RNA-sequencing payloads are not plotted as clinical measurements. Other OSDR studies are cited for future work, but their data are not represented as locally integrated.</p></div><div class="grid two-col">
<div class="card source-card"><div class="btn-row"><span class="pill">HUMAN SPACEFLIGHT · OSD-569</span><span class="pill">PUBLIC PROCESSED DATA</span></div><h3>Whole Blood Measurements from the SpaceX Inspiration4 Mission</h3><p><b>What it contains:</b> Human whole-blood study including Complete Blood Count (CBC), RNA-seq / transcription profiling, epitranscriptome, whole-genome sequencing and targeted genome sequencing assay types. NASA study metadata and a research paper describe sample/subject/timepoint information. Exact CBC column names and file inventory must be read from the current assay files.</p><p><b>Relevance:</b> Blood-cell and molecular changes can support research into immune, hematologic and other biological responses to spaceflight. It does not provide continuous heart rate, SpO₂ or blood pressure.</p><p><b>Access:</b> NASA describes processed data as publicly available; raw/private sequence data require controlled access.</p><a href="https://osdr.nasa.gov/bio/repo/data/studies/OSD-569/" target="_blank" rel="noopener">Open original NASA OSDR study ↗</a><a href="https://www.nature.com/articles/s41526-024-00393-5" target="_blank" rel="noopener">Inspiration4 OSDR data access paper ↗</a></div>
<div class="card source-card"><div class="btn-row"><span class="pill">HUMAN SPACEFLIGHT · OSD-570</span><span class="pill">PUBLIC PROCESSED DATA</span></div><h3>SpaceX Inspiration4 Peripheral Blood Mononuclear Cells (PBMC)</h3><p><b>What it contains:</b> Peripheral blood mononuclear cell biospecimens and associated molecular assay data. Exact assay types, measured features and downloadable file formats are defined by the current study file manifest and assay metadata; inspect these before interpreting individual variables.</p><p><b>Relevance:</b> PBMC molecular profiles can support investigation of immune-cell responses to spaceflight. These are biological research measurements, not bedside vital signs.</p><p><b>Access:</b> Public processed data are described in NASA's OSDR and the associated research paper; raw sequence-level data may be restricted.</p><a href="https://osdr.nasa.gov/bio/repo/data/studies/OSD-570/" target="_blank" rel="noopener">Open original NASA OSDR study ↗</a></div>
<div class="card source-card"><div class="btn-row"><span class="pill">HUMAN SPACEFLIGHT · OSD-571</span><span class="pill">PUBLIC PROCESSED DATA</span></div><h3>SpaceX Inspiration4 Blood Plasma</h3><p><b>What it contains:</b> Plasma biospecimens and associated study assay outputs. The exact analytes/variables depend on the assay files; this application does not infer a universal list from the study title.</p><p><b>Relevance:</b> Plasma molecular measurements can help investigate systemic biological responses before, during and after spaceflight.</p><p><b>Access:</b> NASA lists this as part of the Inspiration4 OSDR human dataset collection; public processed files are available subject to the study's file-level access controls.</p><a href="https://osdr.nasa.gov/bio/repo/data/studies/OSD-571/" target="_blank" rel="noopener">Open original NASA OSDR study ↗</a></div>
<div class="card source-card"><div class="btn-row"><span class="pill">NASA HUMAN RESEARCH</span><span class="pill">RESEARCH CONTEXT</span></div><h3>Spaceflight Standard Measures</h3><p><b>What it measures:</b> NASA describes sleep quality/quantity questionnaires, actigraphy for sleep and activity, mood/team questionnaires, and sensorimotor testing. Sensorimotor measures include movement, balance, heart rate and blood pressure before and after missions.</p><p><b>Relevance:</b> Supports the sleep, fatigue, mood, activity and cardiovascular rationale in ASTROCARE. This page is a research description, not a downloadable continuous telemetry dataset.</p><p><b>Access:</b> Public NASA information page; human research records may have separate access conditions.</p><a href="https://www.nasa.gov/humans-in-space/spaceflight-standard-measures-characterizing-how-humans-adapt-in-space/" target="_blank" rel="noopener">NASA Spaceflight Standard Measures ↗</a></div>
<div class="card source-card"><div class="btn-row"><span class="pill">NASA OSDR / GENELAB</span><span class="pill">REPOSITORY</span></div><h3>Open Science Data Repository (OSDR)</h3><p><b>Data types:</b> Omics, phenotypic, physiological, behavioral, bioimaging, environmental telemetry and hardware data across humans, animals, plants and microbes. Formats include tabular, text, code, imaging and video; raw and processed data.</p><p><b>Relevance:</b> Enables cross-study investigation of spaceflight biology, including molecular mechanisms related to bone, muscle and immune response. Many OSDR studies are non-human; organism and tissue must be checked before applying findings to astronauts.</p><p><b>Access:</b> Most OSDR data are open; human processed data may be public while sequence data can be controlled.</p><a href="https://science.nasa.gov/biological-physical/data/osdr/" target="_blank" rel="noopener">NASA OSDR overview ↗</a><a href="https://science.nasa.gov/reference/osdr-faq/" target="_blank" rel="noopener">NASA OSDR FAQ / API access ↗</a></div>
<div class="card source-card"><div class="btn-row"><span class="pill">NASA RADIATION</span><span class="pill">OPERATIONAL CONTEXT</span></div><h3>Space Radiation</h3><p><b>Research / operations:</b> NASA's Space Radiation Analysis Group supports crew exposure monitoring and radiation safety. NASA notes dosimeters may be worn by crew and returned for analysis.</p><p><b>Relevance:</b> Supports the rationale for recording exposure and maintaining a mission-specific radiation review workflow. ASTROCARE's manual mSv entry is not SRAG data or a dosimeter reading.</p><p><b>Access:</b> Public NASA information page.</p><a href="https://www.nasa.gov/directorates/esdmd/hhp/space-radiation/" target="_blank" rel="noopener">NASA Space Radiation overview ↗</a></div></div>
<div class="card" style="margin-top:14px"><h3 class="panel-title">How NASA data could be integrated next</h3><p class="notice">Use OSDR's public Data File API to retrieve the current manifest, select public processed assay files, inspect the accompanying sample/assay metadata, and import only scientifically interpretable variables. The documented API returns JSON metadata and HTTPS download locations. For RNA-seq, the Inspiration4 paper describes count tables with gene identifiers as rows and samples as columns; process counts with a suitable analysis workflow, not as direct vital-sign values.</p><a class="text-link" href="https://api.nasa.gov/" target="_blank" rel="noopener">NASA Open APIs documentation →</a></div>`}

const cbcMetrics={
 white_blood_cell_count:['White blood cell count','10³/µL'],red_blood_cell_count:['Red blood cell count','10⁶/µL'],hemoglobin:['Hemoglobin','g/dL'],hematocrit:['Hematocrit','%'],platelet_count:['Platelet count','10³/µL'],absolute_neutrophils:['Absolute neutrophils','cells/µL'],absolute_lymphocytes:['Absolute lymphocytes','cells/µL'],absolute_monocytes:['Absolute monocytes','cells/µL'],absolute_eosinophils:['Absolute eosinophils','cells/µL'],absolute_basophils:['Absolute basophils','cells/µL'],mcv:['MCV','fL'],mch:['MCH','pg'],mchc:['MCHC','g/dL'],rdw:['RDW','%'],mpv:['MPV','fL'],neutrophils_percent:['Neutrophils','%'],lymphocytes_percent:['Lymphocytes','%'],monocytes_percent:['Monocytes','%'],eosinophils_percent:['Eosinophils','%'],basophils_percent:['Basophils','%']
};
const cbcOrder=['L-92','L-44','L-3','R+1','R+45','R+82','R+194'];
function cbcRows(){return (window.ASTROCARE_NASA_CBC||[]).filter(x=>x.subject===researchSubject).sort((a,b)=>cbcOrder.indexOf(a.timepoint)-cbcOrder.indexOf(b.timepoint));}
function pageResearch(){const all=window.ASTROCARE_NASA_CBC||[],rows=cbcRows(),meta=cbcMetrics[researchMetric]||cbcMetrics.hemoglobin;return `<div class="research-hero"><div><div class="eyebrow">AUTHENTIC NASA RESEARCH · OSDR</div><h2>Inspiration4 whole-blood CBC</h2><p>Explore the processed complete blood count measurements supplied from NASA OSDR study OSD-569. This research dataset is separate from the synthetic mission telemetry.</p><div class="btn-row"><span class="pill live-pill">NASA SOURCE DATA</span><span class="pill">28 CBC SAMPLES</span><span class="pill">4 CODED PARTICIPANTS</span></div></div><div class="research-orbit">I4</div></div>
<div class="grid three-col research-kpis"><div class="card"><span class="kpi">STUDY</span><strong>OSD-569</strong><small>Whole Blood Measurements</small></div><div class="card"><span class="kpi">COLLECTION WINDOW</span><strong>7 timepoints</strong><small>Pre-flight and post-flight</small></div><div class="card"><span class="kpi">FILE INTEGRATED</span><strong>Processed CSV</strong><small>LSDS-7 CBC transformed table</small></div></div>
<div class="card research-explorer"><div class="card-head"><div><h3>Explore actual CBC measurements</h3><small>SELECT A PARAMETER AND CODED PARTICIPANT</small></div><span class="pill">OSD-569 · CBC ASSAY</span></div><div class="research-controls"><label class="field">Blood parameter<select id="cbc-metric">${Object.entries(cbcMetrics).map(([k,v])=>`<option value="${k}" ${k===researchMetric?'selected':''}>${v[0]}</option>`).join('')}</select></label><label class="field">Participant code<select id="cbc-subject">${['C001','C002','C003','C004'].map(x=>`<option ${x===researchSubject?'selected':''}>${x}</option>`).join('')}</select></label><button class="btn secondary" id="cbc-export">Export selected view ↓</button></div><div class="research-chart-head"><div><strong>${meta[0]}</strong><span>${meta[1]}</span></div><small>Measured values in cyan · supplied lab bounds in amber</small></div><div class="chart-wrap research-chart"><canvas id="cbc-chart"></canvas></div><div class="table-scroll"><table class="data-table research-table"><thead><tr><th>COLLECTION</th><th>MISSION PHASE</th><th>VALUE</th><th>LAB REFERENCE RANGE</th><th>WITHIN RANGE?</th></tr></thead><tbody id="cbc-table">${rows.map(x=>{let m=x.metrics[researchMetric],ok=m.value!==null&&m.min!==null&&m.max!==null;return `<tr><td>${x.timepoint}</td><td>${x.phase}</td><td>${m.value??'—'} ${meta[1]}</td><td>${m.min??'—'} – ${m.max??'—'}</td><td>${!ok?'Not available':m.value<m.min||m.value>m.max?'<span class="range-flag">Outside supplied range</span>':'<span class="range-ok">Within supplied range</span>'}</td></tr>`}).join('')}</tbody></table></div></div>
<div class="grid two-col" style="margin-top:14px"><div class="card"><h3 class="panel-title">What this dataset actually measures</h3><p class="notice">This file contains complete blood count variables: red and white blood cell counts, platelet count, haemoglobin, haematocrit, red-cell indices (MCV, MCH, MCHC, RDW, MPV), leukocyte differential percentages and absolute differential counts. The transformed CSV supplies laboratory reference minima and maxima for many variables.</p><p class="notice">It does <b>not</b> contain continuous heart rate, SpO₂, blood pressure, body temperature, sleep or stress readings.</p></div><div class="card"><h3 class="panel-title">Collection design & limitations</h3><p class="notice">OSD-569 describes four Inspiration4 crew members. This CBC subset contains ground collection timepoints L−92, L−44 and L−3 before launch, and R+1, R+45, R+82 and R+194 after return. There are no in-flight CBC rows in this file.</p><p class="notice">The participant codes are anonymised. Laboratory reference intervals are assay/context reference ranges, not astronaut-specific medical thresholds. This small cohort is descriptive and must not be used to train a clinical alert model.</p></div></div>
<div class="card source-card" style="margin-top:14px"><div class="btn-row"><span class="pill">SOURCE VERIFIED FROM UPLOADED NASA FILES</span><span class="pill">PUBLIC PROCESSED DATA</span></div><h3>NASA OSDR — OSD-569</h3><p><b>Official study:</b> Whole Blood Measurements from the SpaceX Inspiration4 Mission (RNA-seq, epitranscriptome, WGS, clonal hematopoiesis, CBC).</p><p><b>Integrated file:</b> LSDS-7_Complete_Blood_Count_CBC_TRANSFORMED.csv. Original tabular CSV retained in <code>NASA_DATA/OSD-569/</code>; values displayed above are parsed from that file.</p><a href="https://osdr.nasa.gov/bio/repo/data/studies/OSD-569/" target="_blank" rel="noopener">Open original OSD-569 study ↗</a><a href="https://www.nasa.gov/osdr-latest-news-i4-mission-datasets/" target="_blank" rel="noopener">NASA Inspiration4 dataset announcement ↗</a></div>`}
function drawResearchChart(){const rows=cbcRows(),labels=rows.map(x=>x.timepoint),vals=rows.map(x=>x.metrics[researchMetric].value),lo=rows.map(x=>x.metrics[researchMetric].min),hi=rows.map(x=>x.metrics[researchMetric].max);chart('cbc-chart',[{values:vals,color:'#62e0dc'},{values:lo,color:'#e4a84c'},{values:hi,color:'#e4a84c'}],labels,{decimals:2});}
function exportNasaCbc(){const rows=cbcRows(),meta=cbcMetrics[researchMetric],out=[['study','sample','subject','timepoint','phase','parameter','value','unit','reference_min','reference_max'].join(',')];rows.forEach(x=>{let m=x.metrics[researchMetric];out.push(['OSD-569',x.sample,x.subject,x.timepoint,x.phase,meta[0],m.value??'',meta[1],m.min??'',m.max??''].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(','))});download(`OSD-569_${researchSubject}_${researchMetric}.csv`,out.join('\n'),'text/csv');toast('NASA CBC subset exported');}

function pageSettings(){let p=state.profile,s=state.settings,b=p.baseline;return `<div class="section-head"><div><h2>Mission settings & personal baseline</h2><p>Edit the demo crew profile, thresholds and data handling preferences.</p></div><button class="btn secondary" id="reset-demo">Reset demo data</button></div><div class="grid two-col"><div class="card"><h3 class="panel-title">Astronaut profile</h3><form id="profile-form" class="form-grid"><label>Name<input name="name" value="${esc(p.name)}"></label><label>Crew ID<input name="crewId" value="${esc(p.crewId)}"></label><label class="wide">Mission name<input name="mission" value="${esc(p.mission)}"></label><label>Mission day<input name="missionDay" type="number" min="1" value="${p.missionDay}"></label><label>Role<input name="role" value="${esc(p.role)}"></label><div class="wide"><button class="btn primary">Save profile</button></div></form></div><div class="card"><h3 class="panel-title">Personal baseline</h3><form id="baseline-form" class="form-grid">${[['hr','Heart rate (bpm)'],['spo2','SpO₂ (%)'],['temp','Temperature (°C)'],['systolic','Systolic BP'],['diastolic','Diastolic BP'],['sleep','Sleep (hours)'],['stress','Stress (0–10)']].map(([k,l])=>`<label>${l}<input name="${k}" type="number" step="any" value="${b[k]}"></label>`).join('')}<div class="wide"><button class="btn primary">Save baseline</button></div></form></div><div class="card"><h3 class="panel-title">Rule-based alert thresholds</h3><form id="threshold-form" class="form-grid">${[['hrLow','Heart rate low (bpm)'],['hrHigh','Heart rate high (bpm)'],['spo2Low','SpO₂ low (%)'],['tempLow','Temperature low (°C)'],['tempHigh','Temperature high (°C)'],['sleepLow','Sleep minimum (h)'],['stressHigh','Stress flag (0–10)'],['radLimit','Radiation demo limit (mSv)']].map(([k,l])=>`<label>${l}<input name="${k}" type="number" step="any" value="${s[k]}"></label>`).join('')}<div class="wide"><button class="btn primary">Save thresholds</button></div></form><p class="notice">These are user-configurable prototype flags, not NASA medical standards or clinical thresholds.</p></div><div class="card"><h3 class="panel-title">Mission communications & storage</h3><p class="notice">When delayed communications are enabled, alerts and reports remain stored locally until the operator simulates a communications window. No network transmission is implemented.</p><label class="range-row"><input id="delayed-toggle" type="checkbox" class="toggle" ${s.delayed?'checked':''}> <span>Enable delayed communications mode</span></label><hr style="border:0;border-top:1px solid var(--line);margin:15px 0"><p class="notice">Local data currently stored: ${state.records.length} health records, ${state.alerts.length} alerts, ${state.mental.length} wellness check-ins.</p><button class="btn secondary" id="export-csv">Export all health records (CSV)</button></div></div>`}
const pages={overview:['Mission Overview',pageOverview],vitals:['Vital Signs',pageVitals],cardio:['Cardiovascular Health',pageCardio],bone:['Bone & Muscle Health',pageBone],sleep:['Sleep & Fatigue',pageSleep],mental:['Mental Wellness',pageMental],radiation:['Radiation Tracker',pageRadiation],alerts:['Alert Centre',pageAlerts],history:['Health History',pageHistory],research:['NASA Research Data',pageResearch],references:['References & Data Sources',pageReferences],settings:['Settings',pageSettings]};
function render(){chartObjects=[];$('#page-title').textContent=pages[activePage][0];$('#page-content').innerHTML=pages[activePage][1]();document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===activePage));let open=state.alerts.filter(a=>a.status==='OPEN').length;$('#alert-count').textContent=open;$('#alert-count').style.display=open?'inline-block':'none';$('#avatar').textContent=(state.profile.name||'AC').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();$('#last-updated').textContent='Last updated '+fmtTime(nowISO());drawCharts();bindPage();}
function drawCharts(){let rs=sorted().slice(-14),labs=rs.map(x=>new Date(x.date).toLocaleDateString([],{month:'numeric',day:'numeric'}));const draw=(id,key,color,min,max,dec=0)=>chart(id,[{values:rs.map(x=>+x[key]),color}],labs,{min,max,decimals:dec});['hr','spo2','temp','systolic'].forEach((k,i)=>{let id=(activePage==='overview'?['spark-hr','spark-spo2','spark-temp','spark-bp'][i]:activePage==='vitals'?['v-hr','v-sp','v-t','v-bp'][i]:null);if(id)draw(id,k,['#55d9ed','#5c9cff','#f4bd62','#51d6a1'][i]);});
 if(activePage==='overview')draw('overview-chart','hr','#55d9ed');if(activePage==='vitals'){draw('vital-hr','hr','#55d9ed');draw('vital-sp','spo2','#5c9cff',90,100);draw('vital-temp','temp','#f4bd62',35,39,1);chart('vital-bp',[{values:rs.map(x=>+x.systolic),color:'#55d9ed'},{values:rs.map(x=>+x.diastolic),color:'#5c9cff'}],labs,{min:50,max:160});}if(activePage==='cardio'){draw('card-hr','hr','#55d9ed');chart('card-bp',[{values:rs.map(x=>+x.systolic),color:'#55d9ed'},{values:rs.map(x=>+x.diastolic),color:'#5c9cff'}],labs,{min:50,max:160});}if(activePage==='bone'){let ex=state.exerciseLog.slice(-10);chart('bone-chart',[{values:ex.map(x=>+x.duration),color:'#51d6a1'}],ex.map(x=>new Date(x.date).toLocaleDateString([],{month:'numeric',day:'numeric'})),{min:0,max:Math.max(60,...ex.map(x=>+x.duration))});}if(activePage==='sleep')draw('sleep-chart','sleep','#5c9cff',0,10,1);if(activePage==='radiation')draw('rad-chart','radiation','#f4bd62',0,Math.max(.2,...rs.map(x=>+x.radiation)),3);if(activePage==='research')drawResearchChart();
}
function bindPage(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));$('#add-record')?.addEventListener('click',()=>$('#record-dialog').showModal());$('#export-report')?.addEventListener('click',exportReport);$('#export-csv')?.addEventListener('click',exportCSV);$('#export-alerts')?.addEventListener('click',exportAlerts);$('#sync-alerts')?.addEventListener('click',()=>{state.settings.delayed=false;let n=state.pendingReports.length;state.pendingReports=[];save();toast(`Communications window simulated. ${n} queued report(s) marked ready locally.`);render()});document.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=()=>{let a=state.alerts.find(x=>x.id===b.dataset.resolve);if(a){a.status=a.status==='OPEN'?'ACKNOWLEDGED':'OPEN';save();render()}});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Delete this health record? This cannot be undone.')){state.records=state.records.filter(x=>x.id!==b.dataset.delete);save();render();toast('Record deleted')}});
 $('#cbc-metric')?.addEventListener('change',e=>{researchMetric=e.target.value;render()});$('#cbc-subject')?.addEventListener('change',e=>{researchSubject=e.target.value;render()});$('#cbc-export')?.addEventListener('click',exportNasaCbc);$('#history-search')?.addEventListener('input',filterHistory);$('#history-filter')?.addEventListener('change',filterHistory);$('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);Object.keys(state.profile).forEach(k=>{if(f.has(k))state.profile[k]=f.get(k)});state.profile.missionDay=+f.get('missionDay');save();render();toast('Profile saved')});$('#baseline-form')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);for(let [k,v] of f)state.profile.baseline[k]=+v;save();toast('Personal baseline updated')});$('#threshold-form')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);for(let [k,v] of f)state.settings[k]=+v;save();toast('Thresholds saved');render()});$('#delayed-toggle')?.addEventListener('change',e=>{state.settings.delayed=e.target.checked;save();toast('Communications setting updated')});$('#reset-demo')?.addEventListener('click',()=>{if(confirm('Reset all local data to the original synthetic demo?')){state=JSON.parse(JSON.stringify(defaults));save();render();toast('Demo data reset')}});$('#mental-form')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);state.mental.push({id:'m-'+Date.now(),date:nowISO(),mood:f.get('mood'),stress:+f.get('stress'),connected:f.get('connected'),energy:f.get('energy'),note:f.get('note')});let stress=+f.get('stress');if(stress>=state.settings.stressHigh)addAlert('WARNING','Stress check-in',`Self-reported stress ${stress}/10 reached configured threshold.`,'Consider a supportive check-in with crew support.');save();render();toast('Private check-in saved on this device')});$('#log-exercise')?.addEventListener('click',()=>{let type=prompt('Exercise type (e.g. resistance, cycle, treadmill):','Resistance');if(type===null)return;let duration=Number(prompt('Duration in minutes:','40'));if(!Number.isFinite(duration)||duration<0)return toast('Enter a valid duration');let effort=Number(prompt('Perceived effort (0–10):','5'));let note=prompt('Observation (optional):','');state.exerciseLog.push({date:nowISO(),type,duration,effort,note});save();render();toast('Exercise log saved')});$('#sleep-check')?.addEventListener('click',()=>{let sleep=Number(prompt('Sleep duration in hours:','7.5'));if(!Number.isFinite(sleep)||sleep<0||sleep>24)return toast('Enter a valid sleep duration');let quality=prompt('Sleep quality (Very good / Good / Fair / Poor):','Good');let r={...latest(),id:'manual-'+Date.now(),date:nowISO(),sleep,quality,source:'MANUAL ENTRY',notes:'Sleep check-in'};state.records.push(r);analyse(r);save();render();toast('Sleep check-in saved')});}
function filterHistory(){let q=($('#history-search')?.value||'').toLowerCase(),f=$('#history-filter')?.value||'all';let list=sorted().filter(r=>(f==='all'||(r.source||'MANUAL ENTRY')===f)&&JSON.stringify(r).toLowerCase().includes(q));$('#history-body').innerHTML=historyRows(list);document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Delete this health record?')){state.records=state.records.filter(x=>x.id!==b.dataset.delete);save();render()}})}
function navigate(p){if(!pages[p])return;activePage=p;render();$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}
$('#navigation').addEventListener('click',e=>{let b=e.target.closest('[data-page]');if(b)navigate(b.dataset.page)});$('#menu-toggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#banner-close').onclick=()=>$('.demo-banner').remove();$('#quick-report').onclick=exportReport;
$('#record-form').addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),r={id:'r-'+Date.now(),date:nowISO(),hr:+f.get('hr'),spo2:+f.get('spo2'),temp:+f.get('temp'),systolic:+f.get('systolic'),diastolic:+f.get('diastolic'),sleep:+f.get('sleep'),stress:+f.get('stress'),exercise:+f.get('exercise'),radiation:+f.get('radiation'),notes:f.get('notes'),source:'MANUAL ENTRY',quality:'Not recorded',interruptions:null};state.records.push(r);analyse(r);if(state.settings.delayed)state.pendingReports.push({date:nowISO(),type:'NEW_HEALTH_RECORD',recordId:r.id,status:'QUEUED'});save();$('#record-dialog').close();e.target.reset();render();toast('Health record saved locally; rules checked')});
function download(name,content,type='text/plain'){let blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function exportCSV(){let rows=state.records.map(r=>({date:r.date,source:r.source,heart_rate_bpm:r.hr,spo2_percent:r.spo2,temperature_c:r.temp,systolic_mmhg:r.systolic,diastolic_mmhg:r.diastolic,sleep_hours:r.sleep,stress_0_10:r.stress,exercise_minutes:r.exercise,radiation_msv_manual_or_demo:r.radiation,notes:r.notes}));let keys=Object.keys(rows[0]||{date:'',source:''});let csv=[keys.join(','),...rows.map(r=>keys.map(k=>'"'+String(r[k]??'').replace(/"/g,'""')+'"').join(','))].join('\n');download('astrocare_health_history.csv',csv,'text/csv');toast('CSV exported')}
function exportReport(){let r=latest(),open=state.alerts.filter(a=>a.status==='OPEN');let report=`ASTROCARE — MEDICAL REVIEW SUMMARY\nGenerated: ${new Date().toLocaleString()}\n\nIMPORTANT: SYNTHETIC / USER-ENTERED PROTOTYPE DATA. NOT FOR CLINICAL USE. NOT A NASA SYSTEM.\n\nCREW PROFILE\nName: ${state.profile.name}\nCrew ID: ${state.profile.crewId}\nMission: ${state.profile.mission}\nMission day: ${state.profile.missionDay}\n\nLATEST RECORDED VALUES\nHeart rate: ${r.hr} bpm\nSpO2: ${r.spo2}%\nTemperature: ${r.temp} C\nBlood pressure: ${r.systolic}/${r.diastolic} mmHg\nSleep: ${r.sleep} hours\nStress: ${r.stress}/10\nExercise: ${r.exercise} minutes\nRadiation: ${r.radiation} mSv (manual/demo only)\nRecord timestamp: ${r.date}\n\nOPEN RULE-BASED ALERTS\n${open.map(a=>`- ${a.severity} | ${a.parameter} | ${a.reason} | ${a.advice}`).join('\n')||'None'}\n\nPERSONAL BASELINE\n${JSON.stringify(state.profile.baseline,null,2)}\n\nLIMITATIONS\nThis report is generated by an educational prototype using synthetic and/or user-entered readings. It is not a diagnosis, validated medical device, official emergency channel, NASA dataset export, or NASA-endorsed report. Confirm all readings with validated equipment and follow approved flight medical procedures.`;download('astrocare_medical_summary.txt',report);if(state.settings.delayed)state.pendingReports.push({date:nowISO(),type:'MEDICAL_SUMMARY',status:'QUEUED'});save();toast('Medical summary downloaded')}
function exportAlerts(){let txt='ASTROCARE ALERT SUMMARY — DEMONSTRATION ONLY\n\n'+state.alerts.map(a=>`${a.date} | ${a.severity} | ${a.parameter} | ${a.status}\n${a.reason}\nSuggested next step: ${a.advice}\n`).join('\n');download('astrocare_alert_summary.txt',txt);toast('Alert summary exported')}
if(!state.records?.length)state.records=seed();save();render();
